// Super Sketch service worker: saves the whole app on the device so it works without wifi.
// The file list between the markers is generated by `node scripts/precache.mjs` — re-run it when files change.
const VERSION = 'v4';
const CACHE = `supersketch-${VERSION}`;

/* PRECACHE:START */
const CORE = [
  "/",
  "/icons/icon-180.png",
  "/icons/icon-512.png",
  "/icons/icon.svg",
  "/index.html",
  "/manifest.webmanifest",
  "/src/arcade.js",
  "/src/builders.js",
  "/src/colour.js",
  "/src/drawings.js",
  "/src/drawings_more.js",
  "/src/drawings_more2.js",
  "/src/games.js",
  "/src/glyphs.js",
  "/src/grownups.js",
  "/src/main.js",
  "/src/mixup.js",
  "/src/offline.js",
  "/src/phrases.js",
  "/src/reader.js",
  "/src/shapes.js",
  "/src/sound.js",
  "/src/stickers.js",
  "/src/store.js",
  "/src/stories.js",
  "/src/styles.css",
  "/src/sync.js",
  "/src/tracer.js",
  "/src/util.js",
  "/src/wordlist.js"
];
/* PRECACHE:END */

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE).then((cache) => cache.addAll(CORE)).then(() => self.skipWaiting()),
  );
});

self.addEventListener('activate', (event) => {
  event.waitUntil(
    caches.keys()
      .then((keys) => Promise.all(keys.filter((k) => k.startsWith('supersketch-') && k !== CACHE).map((k) => caches.delete(k))))
      .then(() => self.clients.claim()),
  );
});

// Voice clips: cache-first (their names never change). Safari asks for audio in byte ranges, so the saved
// whole file is cut up to answer those requests - that is what makes the voice work offline.
async function audioResponse(req) {
  const cache = await caches.open(CACHE);
  const url = new URL(req.url).pathname;
  let res = await cache.match(url);
  if (!res) {
    try {
      const full = await fetch(url);
      if (!full.ok) return full;
      cache.put(url, full.clone());
      res = full;
    } catch {
      return Response.error();
    }
  }
  const range = req.headers.get('range');
  if (!range) return res;
  const buf = await res.arrayBuffer();
  const m = /bytes=(\d*)-(\d*)/.exec(range);
  const start = m && m[1] ? parseInt(m[1], 10) : 0;
  const end = m && m[2] ? Math.min(parseInt(m[2], 10), buf.byteLength - 1) : buf.byteLength - 1;
  return new Response(buf.slice(start, end + 1), {
    status: 206,
    headers: {
      'Content-Type': res.headers.get('Content-Type') || 'audio/mpeg',
      'Content-Range': `bytes ${start}-${end}/${buf.byteLength}`,
      'Content-Length': String(end - start + 1),
      'Accept-Ranges': 'bytes',
    },
  });
}

// Everything else: online = freshest copy (and refresh the saved one); offline / slow = the saved copy.
self.addEventListener('fetch', (event) => {
  const req = event.request;
  const url = new URL(req.url);
  if (req.method !== 'GET' || url.origin !== self.location.origin || url.pathname.startsWith('/api/')) return;
  if (/^\/audio\/.+\.(mp3|wav)$/.test(url.pathname)) { event.respondWith(audioResponse(req)); return; }
  event.respondWith((async () => {
    const cache = await caches.open(CACHE);
    const fromCache = () => cache.match(req, { ignoreSearch: true }).then((r) => r || (req.mode === 'navigate' ? cache.match('/index.html') : undefined));
    try {
      const res = await Promise.race([
        fetch(req),
        new Promise((_, reject) => setTimeout(() => reject(new Error('timeout')), 4000)),
      ]);
      if (res && res.ok && res.status === 200) cache.put(req, res.clone());
      return res;
    } catch {
      return (await fromCache()) || Response.error();
    }
  })());
});
